), nest AS (
  SELECT * FROM qos_indexer_daily WHERE day = DATE '2026-09-07'
), cmp AS (
  SELECT coalesce(ref.indexer, nest.indexer) AS indexer,
         CASE
           WHEN ref.indexer IS NULL THEN 'not in reference'
           WHEN nest.indexer IS NULL THEN 'not in nest'
           WHEN ref.query_count IS DISTINCT FROM nest.query_count THEN 'query_count'
           WHEN ref.num_200 IS DISTINCT FROM nest.num_200 THEN 'num_200'
           WHEN ref.buckets IS DISTINCT FROM nest.buckets THEN 'buckets'
           WHEN ref.bad_buckets IS DISTINCT FROM nest.bad_buckets THEN 'bad_buckets'
           WHEN ref.worst_bucket_start IS DISTINCT FROM nest.worst_bucket_start THEN 'worst_bucket_start'
           WHEN abs(ref.success_rate - nest.success_rate)
                > 1e-9 * greatest(abs(ref.success_rate), abs(nest.success_rate), 1e-12) THEN 'success_rate'
           WHEN abs(ref.latency_ms - nest.latency_ms)
                > 1e-9 * greatest(abs(ref.latency_ms), abs(nest.latency_ms), 1e-12) THEN 'latency_ms'
           WHEN abs(ref.blocks_behind - nest.blocks_behind)
                > 1e-9 * greatest(abs(ref.blocks_behind), abs(nest.blocks_behind), 1e-12) THEN 'blocks_behind'
           WHEN abs(ref.total_query_fees - nest.total_query_fees)
                > 1e-9 * greatest(abs(ref.total_query_fees), abs(nest.total_query_fees), 1e-12) THEN 'total_query_fees'
         END AS differs
  FROM ref FULL OUTER JOIN nest ON nest.indexer = ref.indexer
